const BIKE_MARKER = 'data:image/png;base64,';
const AUTO_MARKER = 'data:image/png;base64,';

function vehicleKind(vehicle: any): 'bike' | 'auto' | null {
  const info = vehicle?.vehicle_info || vehicle?.vehicle || vehicle;
  const label = [
    typeof vehicle === 'string' ? vehicle : '',
    vehicle?.slug,
    vehicle?.name,
    vehicle?.vehicle_type?.name,
    vehicle?.vehicle_type?.slug,
    info?.name,
    info?.vehicle_type?.name,
    info?.vehicle_type?.slug,
    info?.vehicle_type_name,
  ]
    .filter(value => typeof value === 'string')
    .join(' ')
    .toLowerCase();

  if (/bike|motorcycle|scooter|two.?wheeler/.test(label)) return 'bike';
  if (/auto|rickshaw|three.?wheeler/.test(label)) return 'auto';
  return null;
}

/** Photographic vehicle marker for map layers. The artwork faces north; map
 * components can rotate it using their existing live-heading support. */
export function mapVehicleMarker(vehicle: any, fallback?: string): string | undefined {
  const kind = vehicleKind(vehicle) || vehicleKind(fallback);
  if (!kind) return fallback;
  return kind === 'bike' ? BIKE_MARKER : AUTO_MARKER;
}
